# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Interior kernel: all 27 input positions are guaranteed in-bounds, no boundary checks.
__global__ void maxpool3d_interior_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C,
    int ID, int IH, int IW,
    int OD, int OH, int OW,
    // interior output index ranges [od_lo, od_hi) x [oh_lo, oh_hi) x [ow_lo, ow_hi)
    int od_lo, int od_hi,
    int oh_lo, int oh_hi,
    int ow_lo, int ow_hi,
    int stride, int padding, int dilation
) {
    // Interior output spatial dims
    int iOD = od_hi - od_lo;
    int iOH = oh_hi - oh_lo;
    int iOW = ow_hi - ow_lo;
    int spatial = iOD * iOH * iOW;
    int total = N * C * spatial;

    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total; idx += blockDim.x * gridDim.x) {
        int tmp = idx;
        int local_w = tmp % iOW; tmp /= iOW;
        int local_h = tmp % iOH; tmp /= iOH;
        int local_d = tmp % iOD; tmp /= iOD;
        int c = tmp % C; tmp /= C;
        int n = tmp;

        int od = local_d + od_lo;
        int oh = local_h + oh_lo;
        int ow = local_w + ow_lo;

        int id0 = od * stride - padding;
        int ih0 = oh * stride - padding;
        int iw0 = ow * stride - padding;

        // All 3 kernel positions are in-bounds: no checks needed
        const float* base = input + (n * C + c) * ID * IH * IW;
        float mx = -FLT_MAX;
        // Unrolled 3x3x3 with dilation=3 (compile-time constants)
        #pragma unroll
        for (int kd = 0; kd < 3; kd++) {
            int id = id0 + kd * dilation;
            #pragma unroll
            for (int kh = 0; kh < 3; kh++) {
                int ih = ih0 + kh * dilation;
                #pragma unroll
                for (int kw = 0; kw < 3; kw++) {
                    int iw = iw0 + kw * dilation;
                    float val = __ldg(&base[id * IH * IW + ih * IW + iw]);
                    if (val > mx) mx = val;
                }
            }
        }

        // Write to global output at the correct flat index
        int out_idx = ((n * C + c) * OD + od) * OH * OW + oh * OW + ow;
        output[out_idx] = mx;
    }
}

// Boundary kernel: handles fringe output voxels with full bounds checking.
__global__ void maxpool3d_boundary_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C,
    int ID, int IH, int IW,
    int OD, int OH, int OW,
    int stride, int padding, int dilation
) {
    int total = N * C * OD * OH * OW;
    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total; idx += blockDim.x * gridDim.x) {
        int tmp = idx;
        int ow = tmp % OW; tmp /= OW;
        int oh = tmp % OH; tmp /= OH;
        int od = tmp % OD; tmp /= OD;
        int c  = tmp % C;  tmp /= C;
        int n  = tmp;

        int id0 = od * stride - padding;
        int ih0 = oh * stride - padding;
        int iw0 = ow * stride - padding;

        // Check if this is an interior voxel; if so, skip (handled by interior kernel)
        bool d_ok = (id0 >= 0) && (id0 + 2 * dilation < ID);
        bool h_ok = (ih0 >= 0) && (ih0 + 2 * dilation < IH);
        bool w_ok = (iw0 >= 0) && (iw0 + 2 * dilation < IW);
        if (d_ok && h_ok && w_ok) continue;

        const float* base = input + (n * C + c) * ID * IH * IW;
        float mx = -FLT_MAX;
        #pragma unroll
        for (int kd = 0; kd < 3; kd++) {
            int id = id0 + kd * dilation;
            if (id < 0 || id >= ID) continue;
            #pragma unroll
            for (int kh = 0; kh < 3; kh++) {
                int ih = ih0 + kh * dilation;
                if (ih < 0 || ih >= IH) continue;
                #pragma unroll
                for (int kw = 0; kw < 3; kw++) {
                    int iw = iw0 + kw * dilation;
                    if (iw < 0 || iw >= IW) continue;
                    float val = __ldg(&base[id * IH * IW + ih * IW + iw]);
                    if (val > mx) mx = val;
                }
            }
        }
        output[idx] = mx;
    }
}

torch::Tensor maxpool3d_forward_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dim() == 5, "x must be 5D");

    int N  = x.size(0);
    int C  = x.size(1);
    int ID = x.size(2);
    int IH = x.size(3);
    int IW = x.size(4);

    const int kernel_size = 3;
    const int stride      = 2;
    const int padding     = 1;
    const int dilation    = 3;

    int OD = (ID + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int OH = (IH + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int OW = (IW + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::empty({N, C, OD, OH, OW}, x.options());

    const float* inp = x.data_ptr<float>();
    float* out = output.data_ptr<float>();

    int threads = 256;

    // Compute interior output range:
    // id0 = od*stride - padding >= 0  =>  od >= padding/stride  => od_lo = ceil(padding/stride)
    // id0 + (k-1)*dilation < ID  =>  od*stride - padding + (k-1)*dilation <= ID-1
    //   => od <= (ID - 1 + padding - (k-1)*dilation) / stride
    // Similarly for h and w.
    int od_lo = (padding + stride - 1) / stride;  // ceil(padding/stride)
    int oh_lo = (padding + stride - 1) / stride;
    int ow_lo = (padding + stride - 1) / stride;
    // id0 + 2*dilation < ID  =>  od*stride < ID + padding - 2*dilation
    //   => od < (ID + padding - 2*dilation) / stride
    // od_hi = min(OD, floor((ID + padding - 2*dilation - 1)/stride) + 1)
    int od_hi = (ID + padding - 2 * dilation - 1) / stride + 1;
    int oh_hi = (IH + padding - 2 * dilation - 1) / stride + 1;
    int ow_hi = (IW + padding - 2 * dilation - 1) / stride + 1;
    if (od_hi > OD) od_hi = OD;
    if (oh_hi > OH) oh_hi = OH;
    if (ow_hi > OW) ow_hi = OW;
    if (od_lo > od_hi) od_lo = od_hi;
    if (oh_lo > oh_hi) oh_lo = oh_hi;
    if (ow_lo > ow_hi) ow_lo = ow_hi;

    int iOD = od_hi - od_lo;
    int iOH = oh_hi - oh_lo;
    int iOW = ow_hi - ow_lo;
    int interior_total = N * C * iOD * iOH * iOW;

    if (interior_total > 0) {
        int blocks = (interior_total + threads - 1) / threads;
        if (blocks > 65535) blocks = 65535;
        maxpool3d_interior_kernel<<<blocks, threads>>>(
            inp, out,
            N, C, ID, IH, IW, OD, OH, OW,
            od_lo, od_hi, oh_lo, oh_hi, ow_lo, ow_hi,
            stride, padding, dilation
        );
    }

    // Boundary kernel covers all output voxels but skips interior ones
    int total = N * C * OD * OH * OW;
    {
        int blocks = (total + threads - 1) / threads;
        if (blocks > 65535) blocks = 65535;
        maxpool3d_boundary_kernel<<<blocks, threads>>>(
            inp, out,
            N, C, ID, IH, IW, OD, OH, OW,
            stride, padding, dilation
        );
    }

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs Max Pooling 3D.
        """
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0, dilation: int = 1, return_indices: bool = False, ceil_mode: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the Max Pooling 3D layer.

                Args:
                    kernel_size (int): Size of the kernel for the max pooling operation.
                    stride (int, optional): Stride of the pooling operation. Defaults to None, which means stride is equal to kernel_size.
                    padding (int, optional): Padding applied to the input tensor. Defaults to 0.
                    dilation (int, optional): Spacing between kernel elements. Defaults to 1.
                    return_indices (bool, optional): Whether to return indices of the maximum values. Defaults to False.
                    ceil_mode (bool, optional): When True, the output size is ceil(input_size / stride) instead of floor. Defaults to False.
                """
        self.maxpool = nn.MaxPool3d(kernel_size=kernel_size, stride=stride, padding=padding, dilation=dilation, return_indices=return_indices, ceil_mode=ceil_mode)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies Max Pooling 3D to the input tensor.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, channels, dim1, dim2, dim3).

                Returns:
                    torch.Tensor: Output tensor with Max Pooling 3D applied.
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
