CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Each thread computes two adjacent output positions along W (ow0 and ow1=ow0+1),
// reusing the shared (n,c,od,oh) base and the overlapping kd/kh input rows.
__global__ void maxpool3d_wpair_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C,
    int ID, int IH, int IW,
    int OD, int OH, int OW,
    int stride, int padding, int dilation
) {
    // OW_pairs = ceil(OW/2)
    int OW_pairs = (OW + 1) / 2;
    int total = N * C * OD * OH * OW_pairs;

    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total; idx += blockDim.x * gridDim.x) {
        int tmp = idx;
        int wp  = tmp % OW_pairs; tmp /= OW_pairs;
        int oh  = tmp % OH;       tmp /= OH;
        int od  = tmp % OD;       tmp /= OD;
        int c   = tmp % C;        tmp /= C;
        int n   = tmp;

        int ow0 = wp * 2;
        int ow1 = ow0 + 1;

        int id0 = od * stride - padding;
        int ih0 = oh * stride - padding;
        int iw0_base = ow0 * stride - padding;
        int iw1_base = iw0_base + stride;  // = ow1 * stride - padding

        const float* base = input + (n * C + c) * (ID * IH * IW);

        float mx0 = -FLT_MAX;
        float mx1 = -FLT_MAX;

        #pragma unroll
        for (int kd = 0; kd < 3; kd++) {
